from __future__ import annotations

import base64
import hashlib
import zlib
from pathlib import Path

PAYLOAD = """   """
TARGET = Path("tests/test_release_governance_branch_closure.py")
EXPECTED = "a493848eb0a7cd3f251d671c5e59a08e614ea873af81ff0ee4790a057a4627f8"


def main() -> None:
    compact = "".join(PAYLOAD.split())
    data = zlib.decompress(base64.b64decode(compact))
    observed = hashlib.sha256(data).hexdigest()
    if observed != EXPECTED:
        raise SystemExit(f"normalized source digest mismatch: {observed}")
    TARGET.write_bytes(data)


if __name__ == "__main__":
    main()
